mapper.select:
SELECT pa.id, pa.project_id AS projectId, p.name AS projectName, pa.engineer_id AS engineerId, eu.name AS engineerName, eu.username AS engineerUsername, eu.phone AS engineerPhone, pa.assigned_by AS assignedBy, au.name AS assignedByName, pa.assigned_at AS assignedAt, pa.is_active AS isActive, pa.remark, pa.permission_scope AS permissionScope, pa.expire_at AS expireAt, pa.revoke_reason AS revokeReason, pa.revoked_at AS revokedAt FROM biz_project_assignment pa LEFT JOIN biz_project p ON pa.project_id = p.id LEFT JOIN sys_user eu ON pa.engineer_id = eu.id LEFT JOIN sys_user au ON pa.assigned_by = au.id
AND pa.project_id = #{query.projectId}
AND pa.engineer_id = #{query.engineerId}
AND pa.is_active = #{query.isActive}
AND pa.is_active = 1 AND pa.expire_at IS NOT NULL AND pa.expire_at < DATE_ADD(NOW(), INTERVAL 7 DAY)
ORDER BY pa.assigned_at DESC, pa.id DESC
